import { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The scan bar sweeps across the device, exposing the interior behind it.
// Frames on the 30 fps scene timeline, after `speed`. The ids are public: a
// saved `timing` prop refers to them.

type XRayScanElementId = "scan";

/** The scan's timing does not depend on its props. */
type XRayScanTimingProps = object;

const SCAN_AT = 5;
const SCAN_END = 32;

const xRayScanTimeline = defineTimeline<
  XRayScanElementId,
  XRayScanTimingProps
>(() => [
  {
    id: "scan",
    lane: "Scan",
    label: "scan",
    start: SCAN_AT,
    length: SCAN_END - SCAN_AT,
  },
]);

type XRayScanColors = {
  background: string;
  shell: string;
  detail: string;
  xray: string;
  line: string;
  accent: string;
};

type XRayScanProps = {
  /** Exterior shown ahead of the bar. Defaults to the back of a phone. */
  outside?: ReactNode;
  /** Interior revealed behind the bar. Defaults to white-line phone internals. */
  inside?: ReactNode;
  colors?: Partial<XRayScanColors>;
  /** Phone shell color. Overrides `colors.shell` when set. */
  shell?: string;
  /** Highlighted internal part. Overrides `colors.accent` when set. */
  accent?: string;
  /** Scan line and interior line art. Overrides `colors.line` when set. */
  line?: string;
  /** Background. Overrides `colors.background` when set. */
  background?: string;
  /** "horizontal" sweeps left to right, "vertical" top to bottom. */
  direction?: "horizontal" | "vertical";
  speed?: number;
  /**
   * Moves, trims or stretches the scan, by the ids in `./timeline`.
   * Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<XRayScanElementId>;
};

const xRayScanDefaults = {
  colors: {
    background: "#111111",
    shell: "#E5322D",
    detail: "#111111",
    xray: "#07080A",
    line: "#FFFFFF",
    accent: "#E5322D",
  } as XRayScanColors,
  direction: "horizontal" as const,
  speed: 1,
};

const xRayScanLength = SCAN_END;

const MONO = "ui-monospace, 'SF Mono', Menlo, Consolas, monospace";

type Device = { x: number; y: number; w: number; h: number; r: number };

function Outside({ id, d, c }: { id: string; d: Device; c: XRayScanColors }) {
  const lens = d.w * 0.085;
  return (
    <>
      <defs>
        <linearGradient id={`${id}-gloss`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#FFFFFF" stopOpacity={0.22} />
          <stop offset="0.45" stopColor="#FFFFFF" stopOpacity={0} />
          <stop offset="1" stopColor="#000000" stopOpacity={0.18} />
        </linearGradient>
      </defs>
      <rect x={d.x} y={d.y} width={d.w} height={d.h} rx={d.r} fill={c.shell} />
      <rect
        x={d.x}
        y={d.y}
        width={d.w}
        height={d.h}
        rx={d.r}
        fill={`url(#${id}-gloss)`}
      />
      <rect
        x={d.x + d.w * 0.07}
        y={d.y + d.w * 0.07}
        width={d.w * 0.4}
        height={d.w * 0.4}
        rx={d.w * 0.1}
        fill={c.detail}
        opacity={0.92}
      />
      {[
        [0.17, 0.17],
        [0.37, 0.17],
        [0.17, 0.37],
      ].map(([fx, fy]) => (
        <g key={`${fx}${fy}`}>
          <circle
            cx={d.x + d.w * fx}
            cy={d.y + d.w * fy}
            r={lens}
            fill="#000"
            stroke="#2A2A2A"
            strokeWidth={lens * 0.25}
          />
          <circle
            cx={d.x + d.w * fx - lens * 0.3}
            cy={d.y + d.w * fy - lens * 0.3}
            r={lens * 0.18}
            fill="#FFFFFF"
            opacity={0.6}
          />
        </g>
      ))}
      <circle
        cx={d.x + d.w / 2}
        cy={d.y + d.h * 0.5}
        r={d.w * 0.07}
        fill={c.detail}
        opacity={0.85}
      />
    </>
  );
}

function Inside({ d, c, u }: { d: Device; c: XRayScanColors; u: number }) {
  const X = (f: number) => d.x + d.w * f;
  const Y = (f: number) => d.y + d.h * f;
  const pins = (x: number, y: number, w: number, h: number, n: number) =>
    Array.from({ length: n }, (_, i) => {
      const px = x + ((i + 0.5) / n) * w;
      return `M ${px} ${y - 4 * u} V ${y} M ${px} ${y + h} V ${y + h + 4 * u}`;
    }).join(" ");
  return (
    <>
      <rect x={d.x} y={d.y} width={d.w} height={d.h} rx={d.r} fill={c.xray} />
      <g fill="none" stroke={c.line} strokeWidth={2 * u} strokeLinejoin="round">
        <rect x={d.x} y={d.y} width={d.w} height={d.h} rx={d.r} />
        <rect
          x={X(0.04)}
          y={Y(0.02)}
          width={d.w * 0.92}
          height={d.h * 0.96}
          rx={d.r * 0.82}
          strokeOpacity={0.4}
        />
        {/* Camera ring */}
        {[
          [0.17, 0.17],
          [0.37, 0.17],
          [0.17, 0.37],
        ].map(([fx, fy]) => (
          <g key={`${fx}${fy}`}>
            <circle cx={X(fx)} cy={d.y + d.w * fy} r={d.w * 0.085} />
            <circle
              cx={X(fx)}
              cy={d.y + d.w * fy}
              r={d.w * 0.045}
              strokeOpacity={0.6}
            />
          </g>
        ))}
        {/* Logic board */}
        <path
          d={`M ${X(0.52)} ${Y(0.05)} H ${X(0.9)} V ${Y(0.36)} H ${X(0.1)} V ${Y(0.27)} H ${X(0.52)} Z`}
        />
        <rect
          x={X(0.6)}
          y={Y(0.08)}
          width={d.w * 0.22}
          height={d.h * 0.07}
          rx={2 * u}
        />
        <path
          d={pins(X(0.6), Y(0.08), d.w * 0.22, d.h * 0.07, 6)}
          strokeOpacity={0.6}
          strokeWidth={1.3 * u}
        />
        <rect
          x={X(0.16)}
          y={Y(0.295)}
          width={d.w * 0.16}
          height={d.h * 0.04}
          rx={2 * u}
          strokeOpacity={0.8}
        />
        <rect
          x={X(0.38)}
          y={Y(0.295)}
          width={d.w * 0.12}
          height={d.h * 0.04}
          rx={2 * u}
          strokeOpacity={0.8}
        />
        {/* Battery with wireless coil */}
        <rect
          x={X(0.12)}
          y={Y(0.4)}
          width={d.w * 0.76}
          height={d.h * 0.44}
          rx={6 * u}
        />
        <path
          d={`M ${X(0.42)} ${Y(0.4)} V ${Y(0.385)} H ${X(0.58)} V ${Y(0.4)}`}
        />
        {[0.26, 0.2, 0.14].map((f) => (
          <circle
            key={f}
            cx={X(0.5)}
            cy={Y(0.62)}
            r={d.w * f}
            strokeOpacity={0.45}
          />
        ))}
        <path
          d={`M ${X(0.5)} ${Y(0.47)} V ${Y(0.5)} M ${X(0.485)} ${Y(0.485)} H ${X(0.515)}`}
        />
        {/* Flex cable, speaker and port */}
        <path
          d={`M ${X(0.86)} ${Y(0.36)} V ${Y(0.38)} H ${X(0.92)} V ${Y(0.89)} H ${X(0.66)}`}
          strokeOpacity={0.6}
        />
        <rect
          x={X(0.38)}
          y={Y(0.935)}
          width={d.w * 0.24}
          height={d.h * 0.025}
          rx={d.h * 0.0125}
        />
        {Array.from({ length: 6 }, (_, i) => (
          <circle key={i} cx={X(0.14 + i * 0.035)} cy={Y(0.947)} r={1.8 * u} />
        ))}
      </g>
      {/* The one part in red: the SoC */}
      <g stroke={c.accent} strokeWidth={2.4 * u} fill="none">
        <rect
          x={X(0.6)}
          y={Y(0.17)}
          width={d.w * 0.22}
          height={d.w * 0.22}
          rx={3 * u}
          fill={c.accent}
          fillOpacity={0.22}
        />
        <path
          d={pins(X(0.6), Y(0.17), d.w * 0.22, d.w * 0.22, 5)}
          strokeWidth={1.4 * u}
        />
      </g>
      <text
        x={X(0.5)}
        y={Y(0.79)}
        textAnchor="middle"
        fontFamily={MONO}
        fontSize={12 * u}
        letterSpacing={2 * u}
        fill={c.line}
        opacity={0.7}
      >
        Li-ion 4500 mAh
      </text>
    </>
  );
}

function XRayScanBase(props: XRayScanProps) {
  const {
    outside,
    inside,
    colors,
    shell,
    accent,
    line,
    background,
    direction = xRayScanDefaults.direction,
    speed = xRayScanDefaults.speed,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    xRayScanTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const scan = tl.get("scan");
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const merged = { ...xRayScanDefaults.colors, ...colors };
  const c: XRayScanColors = {
    ...merged,
    shell: shell ?? merged.shell,
    accent: accent ?? merged.accent,
    line: line ?? merged.line,
    background: background ?? merged.background,
  };
  const t = (frame / fps) * 30 * speed;
  const u = Math.min(W, H) / 720;
  const vertical = direction === "vertical";

  const dh = 0.8 * H;
  const dw = dh * 0.49;
  const d: Device = {
    x: (W - dw) / 2,
    y: (H - dh) / 2,
    w: dw,
    h: dh,
    r: dw * 0.17,
  };
  const span = vertical ? H : W;
  const start = vertical ? d.y - 0.1 * H : d.x - 0.12 * W;
  const end = vertical ? d.y + d.h + 0.1 * H : d.x + d.w + 0.12 * W;
  const bar = interpolate(t, [scan.start, scan.end], [start, end], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.sin),
  });
  const scanning = t > scan.start && t < scan.end;
  const band = 0.12 * span;
  const behind = vertical
    ? `inset(0 0 ${H - bar}px 0)`
    : `inset(0 ${W - bar}px 0 0)`;
  const ahead = vertical ? `inset(${bar}px 0 0 0)` : `inset(0 0 0 ${bar}px)`;
  const hot = vertical
    ? `inset(${Math.max(0, bar - band)}px 0 ${H - bar}px 0)`
    : `inset(0 ${W - bar}px 0 ${Math.max(0, bar - band)}px)`;
  const trail = vertical ? "to top" : "to left";

  const insideLayer = inside ?? (
    <svg width={W} height={H} aria-hidden>
      <Inside d={d} c={c} u={u} />
    </svg>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: c.background, overflow: "hidden" }}>
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <filter id={`${id}-glow`} x="-10%" y="-10%" width="120%" height="120%">
          <feGaussianBlur stdDeviation={3 * u} result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </svg>
      <AbsoluteFill style={{ clipPath: ahead }}>
        {outside ?? (
          <svg width={W} height={H} aria-hidden>
            <Outside id={id} d={d} c={c} />
          </svg>
        )}
      </AbsoluteFill>
      <AbsoluteFill style={{ clipPath: behind }}>{insideLayer}</AbsoluteFill>
      {/* Fresh exposure glows brighter just behind the bar. */}
      <AbsoluteFill
        style={{
          clipPath: hot,
          filter: `url(#${id}-glow)`,
          opacity: scanning ? 0.9 : 0,
        }}
      >
        {insideLayer}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          clipPath: behind,
          opacity: scanning ? 1 : 0,
          background: `linear-gradient(${trail}, ${c.line}2E 0px, transparent ${band}px)`,
          backgroundPosition: vertical ? `0 ${bar - H}px` : `${bar - W}px 0`,
          backgroundRepeat: "no-repeat",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: vertical ? 0 : bar - 1.5 * u,
          top: vertical ? bar - 1.5 * u : 0,
          width: vertical ? W : 3 * u,
          height: vertical ? 3 * u : H,
          backgroundColor: c.line,
          boxShadow: `0 0 ${16 * u}px ${4 * u}px ${c.line}AA, 0 0 ${60 * u}px ${12 * u}px ${c.line}33`,
          opacity: scanning ? 1 : 0,
        }}
      />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  direction: {
    type: "enum",
    default: "horizontal",
    variants: {
      horizontal: {},
      vertical: {},
    },
    description: "Direction",
  },
  shell: {
    type: "color",
    default: "#E5322D",
    description: "Shell",
  },
  accent: {
    type: "color",
    default: "#E5322D",
    description: "Accent part",
  },
  line: {
    type: "color",
    default: "#FFFFFF",
    description: "Scan line",
  },
  background: {
    type: "color",
    default: "#111111",
    description: "Background",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["direction","shell","accent","line","background","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  direction: "horizontal",
  shell: "#E5322D",
  accent: "#E5322D",
  line: "#FFFFFF",
  background: "#111111",
  speed: 1,
};

type XRayScanElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof XRayScanBase>;

const XRayScanInner = forwardRef<
  HTMLDivElement,
  XRayScanElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<XRayScan>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <XRayScanBase
          {...(componentProps as unknown as ComponentProps<typeof XRayScanBase>)}
        />
      </div>
    </Sequence>
  );
});

export const XRayScan = Interactive.withSchema({
  Component: XRayScanInner,
  componentName: "<XRayScan>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
